import type { ExecArgs } from "@medusajs/framework/types"
import { ContainerRegistrationKeys } from "@medusajs/framework/utils"

// One wallet per customer, enforced by the database (T-010.5). Link tables are
// generated by `db:sync-links`, which has no custom-index option, so the index
// is added here. `db:migrate` runs migration scripts after module migrations and
// link sync, so the link table exists by now.
export default async function customerWalletUniqueCustomer({ container }: ExecArgs) {
  const pg = container.resolve(ContainerRegistrationKeys.PG_CONNECTION)
  await pg.raw(
    `CREATE UNIQUE INDEX IF NOT EXISTS "UQ_customer_wallet_customer_id"
       ON "customer_customer_wallet_wallet" ("customer_id")
       WHERE "deleted_at" IS NULL`
  )
}
